body {
    font-family: Lato
}

body {
    color: var(--ui-black);
    font: 1rem/1.5rem Lato;
    margin: 0;
    padding: 0
}

@media (max-width: 1023px) {
    body {
        font: .875rem/1rem Lato
    }
    .journey-selector_header_content{
        background-color: none;
    }
    #iconPlane{
        display: none;
    }
}

    .journey-schedule[_ngcontent-gfp-c17] {
        display: flex;
        flex-direction: column
    }
    .journey-schedule-row[_ngcontent-gfp-c17] {
        display: flex;
        flex-wrap: nowrap;
        align-items: flex-start;
        justify-content: space-between
    }
    .journey-schedule-row[_ngcontent-gfp-c17]:first-child {
        align-items: center;
        margin-bottom: 0
    }
    .journey-schedule_duration_time-connections[_ngcontent-gfp-c17],
    .journey-schedule_station[_ngcontent-gfp-c17] {
        display: flex;
        flex-wrap: wrap;
        align-items: center
    }
    .journey-schedule_station[_ngcontent-gfp-c17] {
        flex: 1 1 50%;
        line-height: 1.323
    }
    .journey-schedule_duration_time-connections[_ngcontent-gfp-c17] {
        flex: 0 0 auto;
        flex-direction: column
    }
    .journey-schedule__duration_icon[_ngcontent-gfp-c17] {
        position: relative;
        width: 100%;
        height: 30px;
        text-align: center;
        margin: 0
    }
    .journey-schedule__duration_icon[_ngcontent-gfp-c17]::after {
        content: "";
        display: inline-block;
        font-family: avianca-icons;
        font-weight: 400;
        line-height: 1;
        color: #1b1b1b
    }
    .journey-schedule__duration_icon[_ngcontent-gfp-c17]::before {
        content: '';
        position: absolute;
        left: 50%;
        top: 50%;
        width: 100%;
        height: 1px;
        transform: translateX(-50%)
    }
    .journey-schedule__duration_icon[_ngcontent-gfp-c17]::after {
        font-size: 1.875rem;
        position: absolute;
        left: 50%;
        top: 50%;
        width: 1.875rem;
        min-width: 30px;
        background-color: #fff;
        transform: translate(-50%, -50%)
    }
    .journey-schedule-has-connection[_ngcontent-gfp-c17] .journey-schedule__duration_icon[_ngcontent-gfp-c17]::after {
        content: "";
        color: #1b1b1b
    }
    .journey-schedule_station_city[_ngcontent-gfp-c17],
    .journey-schedule_station_code[_ngcontent-gfp-c17] {
        font-size: 1.125rem;
        color: #1b1b1b;
